#[test]
#[ignore = "compiles a tiny native CoreML graph"]
fn compile_cache_probe() -> Result<(), Box<dyn std::error::Error>> {
    use ort::{ep::{CoreML,coreml::{ModelFormat,ComputeUnits}},session::{Session,builder::GraphOptimizationLevel},value::Tensor};
    use std::{path::PathBuf,time::Instant};
    let model=PathBuf::from(std::env::var("PROBE_MODEL")?);
    let cache=std::env::var("PROBE_CACHE")?;
    let tokens:usize=std::env::var("PROBE_TOKENS")?.parse()?;
    let rows=4usize;
    let scale:f32=std::env::var("PROBE_SCALE")?.parse()?;
    let profile=std::env::var("PROBE_PROFILE")?;
    let mut provider=CoreML::default().with_model_format(ModelFormat::MLProgram).with_compute_units(ComputeUnits::All);
    if cache!="disabled" { provider=provider.with_model_cache_dir(cache); }
    let start=Instant::now();
    let mut session=Session::builder()?.with_execution_providers([provider.build().error_on_failure()])?
        .with_optimization_level(GraphOptimizationLevel::Level3)?.with_disabled_optimizers("MatMulAddFusion")?
        .with_intra_threads(2)?.with_intra_op_spinning(false)?
        .with_dimension_override("batch_size",rows as i64)?.with_dimension_override("sequence_length",tokens as i64)?
        .with_profiling(&profile)?.commit_from_file(model)?;
    let load=start.elapsed().as_secs_f64();
    let start=Instant::now();
    let bge=std::env::var_os("PROBE_BGE").is_some();
    let output=if bge {
        let ids=Tensor::from_array(([rows,tokens],vec![23i64;rows*tokens]))?;
        let mask=Tensor::from_array(([rows,tokens],vec![1i64;rows*tokens]))?;
        session.run(ort::inputs!["input_ids"=>ids,"attention_mask"=>mask])?
    } else { session.run(ort::inputs!["x"=>Tensor::from_array(([rows,tokens,8],vec![0.25f32;rows*tokens*8]))?])? };
    let (shape,values)=output[if bge {"logits"} else {"y"}].try_extract_tensor::<f32>()?;
    if bge { assert_eq!(values.len(),rows); } else { assert_eq!(shape.as_ref(),[rows as i64,tokens as i64,8]); }
    let expected=scale*0.25+0.125;
    let mut max_error=values.iter().map(|x|(x-expected).abs()).fold(0.0f32,f32::max);
    if bge {
        let oracle=std::path::PathBuf::from(std::env::var("PROBE_ORACLE")?);
        let bits:Vec<u32>=values.iter().map(|x| {assert!(x.is_finite());x.to_bits()}).collect();
        if oracle.exists() { let previous:Vec<u32>=serde_json::from_slice(&std::fs::read(oracle)?)?;assert_eq!(bits,previous,"compiled reuse changed logits"); }
        else { std::fs::write(oracle,serde_json::to_vec(&bits)?)?; }
        max_error=0.0;
    }
    assert!(max_error<1e-5,"stale shape or weights: {max_error}");
    let forward=start.elapsed().as_secs_f64();drop(output);
    let path=session.end_profiling()?;
    let events:serde_json::Value=serde_json::from_slice(&std::fs::read(&path)?)?;
    let coreml=events.as_array().unwrap().iter().any(|event|event["args"]["provider"]=="CoreMLExecutionProvider");
    assert!(coreml,"provider registration did not execute the graph: {path}");
    println!("compile_probe tokens={tokens} scale={scale} load_seconds={load:.9} forward_seconds={forward:.9} max_error={max_error} profile={path}");
    Ok(())
}
